+    await schedulingApi.declineSession('s1', { expected_start_at: '2026-10-06T17:00:00.000Z' });
+    expect(post).toHaveBeenLastCalledWith('/scheduling/sessions/s1/decline', {
+      expected_start_at: '2026-10-06T17:00:00.000Z',
+    });
+  });
+});

