+    networkCode === 'ERR_NETWORK' ||
+    networkCode === 'ECONNABORTED' ||
+    networkCode === 'ETIMEDOUT' ||
+    (err instanceof Error && err.message === 'Network Error')
+  ) {
+    return audience === 'coach'
