+      id: 'n-1',
+      kind: 'coach',
+      title: 'Session confirmed',
+      body: 'Your session on Tue 3 Mar at 10:00 is confirmed.',
+      read: false,
+      createdAt: '2027-03-01T10:00:00.000Z',
+      actionScreen: 'CalendarSession',
+      actionParams: { sessionId: 's-1' },
+    });
+  });
